export function pendingRealmTalent(nivel: number): RealmTalent {
  return {
    nivel,
    nome: 'Em revisão',
    desc: 'Conteúdo ainda não transcrito para este arquétipo/reino no acervo (verificar Arquétipos no vault).',
    revisao: true,
  };
}